    private List<com.ruoyi.medical.workflow.TaskRunRecoveryProtocolV2.UndispatchedFailureV2> undispatchedOriginal(EnterpriseAccess.Admission a,Reference ref)throws Exception{
        var rows=db.queryForList("SELECT operation_id,response_ref FROM operation_record WHERE tenant_id=? AND subject_id=? AND target_id=? AND operation_name=? ORDER BY created_at,operation_id LIMIT ? FOR UPDATE",ref.tenantId(),a.actorId(),ref.runId(),UNDISPATCHED,ref.maximumSteps()+1);if(rows.size()>ref.maximumSteps())deny();var result=new ArrayList<com.ruoyi.medical.workflow.TaskRunRecoveryProtocolV2.UndispatchedFailureV2>();
        for(var row:rows){var value=reader.readTree(text(row,"response_ref"));var step=value.required("request").required("step_id").asText();var saved=read(a,ref,text(row,"operation_id"),UNDISPATCHED,step,value.required("request")).orElseThrow();var f=reader.treeToValue(saved.required("result"),com.ruoyi.medical.workflow.TaskRunRecoveryProtocolV2.UndispatchedFailureV2.class);same(journal.hash(saved.required("evidence")),f.receiptSha256());same(step,f.stepId());same(ref.runId(),f.runId());
            var steps=db.queryForList("SELECT input_sha256,lease_generation,status FROM run_step WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),ref.runId(),step);if("INPUT_UNMATERIALIZED".equals(f.kind())){if(!steps.isEmpty())bad();}else{var actual=one(steps);same("FAILED",text(actual,"status"));same("0",number(actual,"lease_generation"));same(f.inputSha256(),text(actual,"input_sha256"));}result.add(f);}
        return List.copyOf(result);
    }
