        return authority.execute(http,ref,CONSUME_CANCEL,p->{var witness=cancellationCommand(p,command);same("CANCEL_REQUESTED",p.status());var receipt=new CommandReceipt(command.commandId(),command.commandSha256(),ref.runId(),true,List.of());write(p,id,COMMAND,command.commandId(),request,witness,json.tree(receipt));return receipt;});
